#include <stdio.h>

// Returns how many times c appears in the string s.
size_t count_char(const char *s, char c) {
    size_t n = 0;
    for (const char *p = s; *p != '\0'; p++) {
        if (*p == c) {
            n++;
        }
    }
    return n;
}

int main(void) {
    char word[] = "mississippi";
    printf("s: %zu\n", count_char(word, 's'));
    printf("p: %zu\n", count_char(word, 'p'));
    printf("s from index 4: %zu\n", count_char(word + 4, 's'));
    printf("z: %zu\n", count_char("", 'z'));
    return 0;
}

#include <stdio.h>

// The third strlen from the notebook: walk p to the '\0', then subtract.
size_t my_strlen(const char *str) {
    const char *p = str;
    while (*p != '\0') {
        p++;
    }
    return p - str;
}

int main(void) {
    printf("%zu\n", my_strlen("hello"));
    printf("%zu\n", my_strlen(""));
    printf("%zu\n", my_strlen("CISC220" + 4));
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(void) {
    char src[] = "01234";
    size_t len = strlen(src);

    // len + 1 to make sure that there is space for the null terminator
    char dest1[len + 1];
    strcpy(dest1, src);
    printf("src   = %s\n", src);
    printf("dest1 = %s\n", dest1);

    // print the return value instead
    char dest2[len + 1];
    printf("dest2 = %s\n", strcpy(dest2, src));

    // copy into the middle of the destination array
    char dest3[] = "abcde-----";
    strcpy(dest3 + len, src);
    printf("dest3 = %s\n", dest3);

    // copy the end of a string into a destination array
    char *s = "CISC220";
    char dest4[4];
    strcpy(dest4, s + 4);
    printf("dest4 = %s\n", dest4);

    return 0;
}

