#include <stdio.h>

// Copies the string src (including its '\0') into dest and returns dest.
// dest must have room for strlen(src) + 1 chars.
char *my_strcpy(char *dest, const char *src) {
    char *d = dest;
    const char *s = src;
    while (*s != '\0') {
        *d = *s;
        d++;
        s++;
    }
    *d = '\0';
    return dest;
}

int main(void) {
    char word[] = "pointer";
    char copy[8];
    my_strcpy(copy, word);
    copy[0] = 'P';
    printf("%s %s\n", word, copy);
    char line[] = "AB-----";
    printf("%s\n", my_strcpy(line + 2, "cd"));
    printf("%s\n", line);
    return 0;
}

