#include <stdio.h>
#include <string.h>

// Puts a followed by b into dest, which has room for cap chars.
// Returns 1 on success. If the joined string and its '\0' do not fit,
// returns 0 and leaves dest unchanged.
int join(char *dest, size_t cap, const char *a, const char *b) {
    size_t need = strlen(a) + strlen(b) + 1;
    if (need > cap) {
        return 0;
    }
    strcpy(dest, a);
    strcat(dest, b);
    return 1;
}

int main(void) {
    char greeting[16];
    if (join(greeting, sizeof(greeting), "Happy ", "Holidays")) {
        printf("%s\n", greeting);
    }
    if (!join(greeting, sizeof(greeting), "Happy ", "New Year's Eve")) {
        printf("too long for %zu chars\n", sizeof(greeting));
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: ordered word...\n");
        exit(1);
    }
    for (int i = 1; i < argc; i++) {
        if (strlen(argv[i]) > 20) {
            fprintf(stderr, "ordered: argument %d is longer than 20 characters\n", i);
            exit(1);
        }
    }
    for (int i = 2; i < argc; i++) {
        if (strcmp(argv[i - 1], argv[i]) > 0) {
            printf("arguments out of order:\n");
            printf("  %s\n", argv[i - 1]);
            printf("  %s\n", argv[i]);
            exit(1);
        }
    }
    printf("arguments are in order\n");
    return 0;
}
